SERIES = []
for part in RAW.strip().split(';'):
    pat, y = part.rsplit('=', 1)
    SERIES.append((re.compile(r'(?<![a-z])(' + pat + r')', re.I), int(y)))
def series_year(text):
    for rx, y in SERIES:
        if rx.search(text): return y
    return 0

