SHORT = {'doug', 'sonic', 'arthur', 'barney', 'batman', 'superman', 'aladdin', 'hercules', 'reboot', 'franklin', 'recess', 'clifford', 'yogi', 'popeye', 'mask', 'jem', 'guts', 'zelda', 'babar', 'kipper', 'maisy', 'oswald', 'madeline', 'caillou', 'bonkers', 'rocko', 'scooby', 'peanuts', 'toonami', 'clarissa', 'wishbone', 'goosebumps', 'trigun', 'zoids', 'medabots', 'teknoman', 'digimon', 'rugrats', 'catdog', 'kablam', 'voltron', 'robotech', 'thundercats', 'silverhawks', 'heathcliff', 'snorks', 'smurfs', 'ducktales', 'talespin', 'gargoyles', 'animaniacs', 'freakazoid', 'exosquad', 'visionaries', 'inhumanoids', 'centurions', 'bravestarr', 'thundarr', 'jayce', 'veggietales', 'kidsongs', 'teletubbies', 'beetlejuice', 'beetleborgs', 'cardcaptors', 'spongebob', 'pokemon', 'tmnt'}
def series_name(text):
    for rx, y in SERIES:
        m = rx.search(text)
        if not m: continue
        k = m.group(1).lower().replace('’', "'")
        if k in SHORT and m.start() > 12: continue
        if m.start() > 40: continue
        return y, CANON.get(k) or CANON.get(k.replace("'", '')) or k.upper()
    return 0, ''
